r"""Instalador de la decisión D30 para el repo de Faro Seguros RAG.

Qué instala (borrado de documentos con cascada + smoke auto-limpio):

  1. Puerto DocumentRepository.delete + adapter SQLAlchemy (un solo
     DELETE; chunks y contenido caen por la FK ON DELETE CASCADE).
  2. Ruta DELETE /api/documents/{id} — 204 borrado / 404 inexistente /
     409 en plena ingesta (pending/processing); el hash (D03) queda
     libre y re-subir registra de nuevo.
  3. Tests del contrato (+6) y el doble actualizado.
  4. Frontend: eliminarDocumento en api.js + botón «Eliminar» con
     confirmación en DocumentsView.jsx + estilo.
  5. Smoke: la sección 17 borra SU sonda al terminar (DELETE 204 +
     GET 404 + 0 chunks en pgvector) — 58 comprobaciones esperadas.
  6. README/DECISIONS (D30) y Makefile con los conteos al día.

Qué NO toca: backend/app/evaluation/runner.py (el fix del guard ya está
aplicado en tu árbol y verificado por tu smoke).

Seguridad del instalador: por cada archivo comprueba que tu contenido
local sea EXACTAMENTE el esperado (sha256 del estado base) antes de
escribir; si difiere, lo salta y te avisa — nunca sobreescribe cambios
propios. Es idempotente: re-correlo y dirá «ya aplicado». Todo el
contenido va embebido en base64 (nada puede corromperse en tránsito).

Uso, desde la raíz del repo (donde están backend/ y scripts/):

    python3 instala_d30.py

Después revisa el diff, corre la suite, rebuilda y smoke:

    git diff --stat
    cd backend && python -m pytest -q && cd ..   # 216 esperados
    docker compose up --build -d api frontend    # código horneado en imagen
    make smoke                                   # 58 OK / 0 FALLOS esperado

Las sondas de corridas ANTERIORES siguen en la lista: bórralas con el
botón nuevo (http://localhost:5173) o de una vez:

    docker compose exec db psql -U faro -d faro \
      -c "DELETE FROM documents WHERE filename = 'sonda.txt';"
"""

