# Solo se instalan si el guard __main__ del runner está al final del
# módulo: hablan de 216 tests y del pin de regresión del guard, que
# exige ese layout (mismo criterio que el propio test).
_CONDICIONALES = {
    "README.md",
    "DECISIONS.md",
    "backend/tests/test_evaluation.py",
}


def _sha(datos: bytes) -> str:
    return hashlib.sha256(datos).hexdigest()


def _guard_al_final(ruta: Path) -> bool:
    """True si todo guard __main__ de runner.py es la última sentencia.

    Misma semántica que el pin de la suite (test_evaluation.py): un guard
    a mitad de módulo hace que ``python -m`` ejecute main() antes de
    ligar las defs posteriores (el NameError de D28/D29).
    """
    try:
        cuerpo = ast.parse(ruta.read_text(encoding="utf-8")).body
    except Exception:
        return False
    for i, nodo in enumerate(cuerpo):
        if (
            isinstance(nodo, ast.If)
            and isinstance(nodo.test, ast.Compare)
            and isinstance(nodo.test.left, ast.Name)
            and nodo.test.left.id == "__name__"
            and len(nodo.test.ops) == 1
            and isinstance(nodo.test.ops[0], ast.Eq)
            and len(nodo.test.comparators) == 1
            and isinstance(nodo.test.comparators[0], ast.Constant)
            and nodo.test.comparators[0].value == "__main__"
            and i != len(cuerpo) - 1
        ):
            return False
    return True


def _raiz() -> Path:
    aqui = Path.cwd()
    for candidata in (aqui, *aqui.parents):
        if (candidata / "backend" / "app").is_dir() and (
            candidata / "scripts" / "smoke_stack.sh"
        ).is_file():
            return candidata
    sys.exit(
        "ERROR: no encuentro la raíz del repo (backend/app y scripts/\n"
        "smoke_stack.sh). Corre el instalador desde la raíz del proyecto."
    )


def main() -> int:
    raiz = _raiz()
    print(f"Instalador D30 — repo: {raiz}")
    print()

    guard_ok = _guard_al_final(
        raiz / "backend" / "app" / "evaluation" / "runner.py"
    )
    if guard_ok:
        print("[ OK ] runner.py: guard __main__ al final (fix D28/D29 presente)")
    else:
        print("[AVISO] runner.py sin guard al final del módulo")
        print("        -> instalo el código D30, pero NO README/DECISIONS/")
        print("           test_evaluation (hablan de 216 tests y del pin AST).")
        print("        Arregla el runner y re-corre este instalador.")
    print()

    aplicados: list[str] = []
    ya_estaban: list[str] = []
    saltados: list[tuple[str, str]] = []

    for ruta_rel in sorted(_PAQUETE):
        spec = _PAQUETE[ruta_rel]
        destino = raiz / ruta_rel
        nuevo = spec["nuevo"].encode("utf-8")

        if ruta_rel in _CONDICIONALES and not guard_ok:
            saltados.append((ruta_rel, "condicional: guard del runner no verificado"))
            continue

        if not destino.exists():
            saltados.append((ruta_rel, "el archivo no existe en tu repo"))
            continue

        actual = destino.read_bytes()
        if _sha(actual) == _sha(nuevo):
            ya_estaban.append(ruta_rel)
            continue
        if _sha(actual) != spec["base"]:
            saltados.append(
                (ruta_rel, "contenido local inesperado (¿lo editaste?): NO se toca")
            )
            continue

        destino.write_bytes(nuevo)
        if _sha(destino.read_bytes()) == _sha(nuevo):
            aplicados.append(ruta_rel)
        else:
            saltados.append((ruta_rel, "verificación post-escritura falló"))

    ancho = max(len(r) for r in _PAQUETE)
    for ruta in aplicados:
        print(f"  [instalado] {ruta:{ancho}}  {_sha((raiz / ruta).read_bytes())[:16]}")
    for ruta in ya_estaban:
        print(f"  [ ya estaba] {ruta:{ancho}}  (idempotente: contenido idéntico)")
    for ruta, motivo in saltados:
        print(f"  [  saltado ] {ruta:{ancho}}  {motivo}")

    print()
    print(f"Resumen: {len(aplicados)} instalados, {len(ya_estaban)} ya estaban, "
          f"{len(saltados)} saltados de {len(_PAQUETE)}")
    if aplicados:
        print()
        print("Siguientes pasos:")
        print("  1) Revisa el diff:        git diff --stat")
        print("  2) Suite (216 esperados): cd backend && python -m pytest -q")
        print("  3) Rebuild (código horneado en la imagen, no en volume):")
        print("       docker compose up --build -d api frontend")
        print("  4) Smoke (58 OK esperado): make smoke")
        print("  5) Sondas viejas (una vez): botón «Eliminar» en el frontend, o todo de golpe:")
        print("     docker compose exec db psql -U faro -d faro -c \"DELETE FROM documents WHERE filename = 'sonda.txt';\"")
    return 0 if not saltados else 1


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except BrokenPipeError:
        # pipe a head/less cortado: salir limpio, sin traceback
        import os

        os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        raise SystemExit(1)
